// near 78,000. Bucket every emitted file into `assets/<00-ff>/` so no single directory comes close.
// The `_headers` rule stays correct: a Netlify `/assets/*` splat matches nested paths too.
const ASSET_SHARDS = 256;

const assetShard = (name: string): string => {
  let hash = 0;
  for (let index = 0; index < name.length; index += 1) {
    hash = (Math.imul(hash, 31) + name.charCodeAt(index)) >>> 0;
  }
