import { spawnSync } from "node:child_process";
import { cpSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
import { NON_ROOT_LOCALES, parseRequestedLocales } from "../.vitepress/i18n.ts";

const require = createRequire(import.meta.url);
const vitepressBin = join(dirname(require.resolve("vitepress/package.json")), "bin", "vitepress.js");

const distDir = resolve(process.env.DOCS_DIST_DIR ?? ".vitepress/dist");
const stagingDir = resolve(".vitepress/.locales");

// Root last: it owns the shared root-level files (404.html, llms.txt), so its copies must win.
const locales = [...parseRequestedLocales(process.env.DOCS_LOCALES, NON_ROOT_LOCALES), "root"];

rmSync(stagingDir, { recursive: true, force: true });
rmSync(distDir, { recursive: true, force: true });
mkdirSync(distDir, { recursive: true });

console.log(`📋 Building ${locales.length} locales`);

for (const [index, locale] of locales.entries()) {
  const localeOut = join(stagingDir, locale);
  const started = Date.now();
  const result = spawnSync(process.execPath, [vitepressBin, "build"], {
    stdio: "inherit",
    env: { ...process.env, DOCS_LOCALE: locale, DOCS_OUT_DIR: localeOut },
  });
  if (result.status !== 0) {
    console.error(`✗ ${locale}: build failed`);
    process.exit(result.status ?? 1);
